"""Pending lessons authored from lib/vsprintf.c lines 1–741, not a whole-file claim."""
def register(topic, q, detail):
    def lesson(title, symbol, why, principle, use, reading, qa, cards):
        topic(title, '라이브러리·알고리즘', 'lib/vsprintf.c', symbol, why, principle, use, reading,
              *(q(*item) for item in qa), details=[detail(*item) for item in cards])
    lesson('Simple 숫자 변환·소비 길이와 오류 계약', 'simple_strntoull',
      '커널의 오래된 숫자 변환 API를 읽으며 변환 결과, 읽은 길이, 오류 보고가 서로 다른 계약임을 배웁니다.',
      '먼저 _parse_integer_fixup_radix가 진법과 prefix를 결정합니다. Prefix 길이가 max_chars보다 작으면 남은 길이만 _parse_integer_limit에 전달합니다. 반환 rv에서 KSTRTOX_OVERFLOW bit를 지운 숫자만큼 cp를 이동하고 선택적으로 endp를 갱신합니다. Prefix를 담기에 너무 짧으면 결과 0과 startp+max_chars를 반환합니다. Overflow 상태를 오류 코드로 보고하지 않습니다.',
      '호출 뒤 endp로 어디까지 읽었는지 확인합니다. 새로 작성하는 일반 숫자 입력 검증에는 원본 문서가 권하는 kstrtoull의 오류 계약을 확인합니다. max_chars를 지정했다고 prefix 판정까지 무조건 그 길이 안에서만 메모리를 읽는다고 가정하지 않습니다.',
      'prefix_chars 비교, 남은 길이, overflow bit 제거, endp 갱신 순서를 읽으세요.',
      [('Overflow bit는 어떤 목적으로 마스킹하는가?', '소비한 문자 수에서 상태 bit를 제거한다', '오버플로를 반드시 ERANGE로 반환한다', 'rv에는 길이와 상태가 함께 있습니다. 이 함수는 상태를 지운 길이로 cp만 전진시키며 오류 코드 반환 API가 아닙니다.'),
       ('필드가 prefix만 담을 수 있어 숫자를 읽지 못하면?', '결과 0과 필드 끝의 endp를 제공한다', '항상 prefix 뒤 첫 숫자까지 읽는다', 'prefix_chars < max_chars가 거짓이면 cp=startp+max_chars이며 초기 result=0이 유지됩니다.')],
      [('무제한 Wrapper', 'simple_strtoull은 INT_MAX를 전달하고 simple_strtoul은 그 결과를 unsigned long으로 반환합니다. Long의 크기가 다른 환경에서 좁아지는 변환을 오류 검사라고 설명하지 않습니다.'),
       ('읽기와 변환의 제한', '진법 보정은 prefix 길이 검사 전에 호출됩니다. 유효한 입력 저장공간은 caller가 제공해야 하며 max_chars=0이 임의 pointer를 안전하게 만든다는 의미가 아닙니다.')])
    lesson('Simple 부호 변환·Minus와 제한 길이', 'simple_strntoll',
      '부호 문자를 처리하는 작은 wrapper에서도 길이 소비와 signed 변환 조건을 직접 확인해야 합니다.',
      '첫 문자가 minus이고 max_chars>0이면 cp+1과 max_chars-1을 unsigned helper에 전달한 뒤 음수화합니다. 그렇지 않으면 같은 cp와 길이를 전달합니다. 조건은 *cp를 먼저 평가합니다. simple_strtoll은 INT_MAX를 전달하고 simple_strtol도 minus일 때 unsigned long 변환 결과를 음수화합니다. Plus나 선행 공백을 별도로 건너뛰는 코드가 없습니다.',
      '유효한 입력 주소와 반환 타입의 범위를 확인합니다. 숫자 입력의 전체 유효성 및 범위 검사가 필요한 코드에는 kstrtoll 계열의 계약을 사용합니다. 길이 0이라고 첫 byte 접근까지 없어지는 것으로 해석하지 않습니다.',
      '*cp 검사와 max_chars 비교의 순서, minus를 소비한 뒤 남은 길이를 읽으세요.',
      [('Minus 한 글자만 허용된 필드에서는 숫자에 남는 길이가?', '0이다', '1이 그대로 전달된다', '부호를 소비하면서 max_chars-1을 전달합니다. 숫자 결과는 0이며 endp는 부호 뒤를 가리킵니다.'),
       ('max_chars=0이면 첫 문자 접근도 생략되는가?', '*cp가 조건에서 먼저 평가된다', 'max_chars를 먼저 검사해 주소를 전혀 읽지 않는다', '실제 조건은 *cp == minus && max_chars > 0입니다. 단락 평가의 왼쪽에서 문자를 읽습니다.')],
      [('Plus와 공백', '이 wrapper에는 plus나 공백을 처리하는 branch가 없습니다. 일반 C 라이브러리 strtoll과 이름이 비슷하다고 같은 문법이라고 가정하지 않습니다.'),
       ('결과와 상태', 'Simple 함수는 결과값을 직접 반환합니다. kstrtoll의 성공/오류 코드와 출력 매개변수 패턴을 이 함수에 그대로 적용하면 입력 검증을 빠뜨릴 수 있습니다.')])
    lesson('Format 숫자 읽기·Pointer 갱신과 Do While', 'skip_atoi',
      '출력 형식 안의 폭과 정밀도를 읽는 함수에서 pointer의 pointer와 반복문 전제를 이해합니다.',
      'int i를 0으로 시작하고 i=i*10+*((*s)++)-\'0\'으로 현재 문자를 더하면서 caller의 pointer를 전진시킵니다. do while이므로 최소 한 번 실행하고 이후 isdigit(**s)인 동안 반복합니다. Signed int 누적에 별도 overflow 검사가 없는 내부 helper입니다.',
      '첫 문자가 숫자인 문맥에서 사용하고 형식 파서의 폭 제한과 함께 읽습니다. 일반 사용자 입력을 안전하게 변환하는 독립 API로 꺼내 쓰지 않습니다. s 자체와 *s가 가리키는 문자열 주소를 구분합니다.',
      '두 단계 역참조, postfix ++, 첫 반복을 보장하는 do while을 읽으세요.',
      [('문자열 123x를 읽은 뒤 caller의 pointer는?', 'x를 가리킨다', '원래의 1에 남는다', '각 숫자마다 (*s)++가 caller가 가진 주소를 갱신합니다. 다음 문자가 숫자가 아니면 반복을 끝냅니다.'),
       ('첫 문자부터 숫자인지 이 함수가 먼저 검사하는가?', '첫 반복 전에 검사하지 않는다', '검사 후 숫자가 없으면 언제나 오류를 반환한다', 'do while 본문이 먼저 실행됩니다. Caller가 숫자 위치라는 전제를 지켜야 합니다.')],
      [('값의 자릿수', '기존 i에 10을 곱하면 decimal 한 자리를 왼쪽으로 옮깁니다. ASCII 숫자에서 0의 코드를 빼면 0부터 9의 값이 됩니다.'),
       ('Overflow 한계', '원본 helper에는 ERANGE branch가 없습니다. 큰 폭 문자열에 대한 안전성은 이 함수만으로 증명할 수 없으며 형식 파서의 후속 처리도 읽어야 합니다.')])
    lesson('Decimal 두 자리 Table·역순 출력과 Endian', 'put_dec_trunc8',
      '자주 호출되는 숫자 출력에서 lookup table과 상수 곱셈을 결합해 반복 비용을 줄이는 원리를 배웁니다.',
      'decpair는 0부터 99까지 100개의 u16 항목을 가지며 각 항목의 메모리 byte는 일의 자리, 십의 자리 순서입니다. cpu_to_le16을 사용해 두 byte의 저장 순서를 맞춥니다. put_dec_trunc8은 r을 100으로 나눈 몫과 나머지를 반복 계산하고 나머지의 두 문자를 한 번에 저장합니다. 마지막 한 자리에서는 pointer를 1만 전진시키지만 u16 저장 자체는 두 byte입니다.',
      '2-byte 정렬과 실제 저장에 충분한 공간을 가진 내부 buffer를 제공합니다. 반환 pointer의 차이와 메모리 저장 폭을 구분합니다. 반환 구간은 역순 숫자라 최종 사용 단계에서 뒤집고, NUL 종료는 이 함수가 제공하지 않습니다.',
      'decpair 매크로, u16 저장, r<10일 때 1과 2의 반환 길이를 연결하세요.',
      [('decpair[42]의 메모리 두 문자는?', '2 다음 4이다', '4 다음 2이다', '역순 숫자를 모으므로 일의 자리를 먼저 저장합니다. cpu_to_le16이 메모리 byte 순서를 맞춥니다.'),
       ('r=0일 때 반환 길이가 1이면 실제 저장도 1byte인가?', 'u16으로 2byte를 저장한다', '1byte만 저장하고 두 번째 byte는 건드리지 않는다', '두 개의 0을 저장한 뒤 반환 pointer만 1 전진합니다. Buffer를 반환 길이만큼만 잡으면 충분하다고 가정할 수 없습니다.')],
      [('고정소수점 나눗셈', 'r<10^8에서 (r*(u64)0x28f5c29)>>32는 r/100의 정수 몫입니다. 더 작은 단계에서는 (r*0x147b)>>19를 사용합니다. 정확성은 제한된 입력 범위에 의존합니다.'),
       ('알고리즘의 목적', '원본은 /proc와 /sys 숫자 출력이 빈번하다고 설명합니다. 두 자리씩 처리하면 한 자리씩 곱셈하는 방식보다 곱셈 횟수를 줄일 수 있지만 모든 환경의 실측 속도 향상을 이 읽기만으로 주장하지 않습니다.')])
    lesson('64bit Decimal 분해·1억 단위 Chunk', 'put_dec_full8',
      '큰 정수를 작은 진법의 묶음으로 분해할 때 아래쪽 묶음의 선행 0이 왜 필요한지 이해합니다.',
      '64bit long·long long 설정의 put_dec는 n이 10^8 이상이면 do_div로 나머지를 얻고 n을 몫으로 갱신합니다. 아래쪽 묶음은 put_dec_full8로 항상 8자리 역순 출력합니다. 필요한 경우 한 번 더 묶음을 분리한 뒤 맨 위의 작은 n만 put_dec_trunc8로 출력합니다. full8은 두 자리 table 저장을 네 번 수행합니다.',
      '선택 CONFIG의 BITS_PER_LONG과 BITS_PER_LONG_LONG 분기를 확인합니다. do_div가 n을 직접 갱신한다는 매크로 계약을 기억합니다. 고정 폭 아래쪽 묶음과 가변 폭 최상위 묶음을 바꾸지 않습니다.',
      'do_div 반환 나머지와 수정된 몫, full8의 네 번 저장을 읽으세요.',
      [('100000001의 아래쪽 묶음 1은 몇 자리로 저장하는가?', '00000001의 8자리이다', '1 한 자리이다', '전체 숫자를 복원하려면 아래 묶음이 정확히 8자리를 차지해야 합니다. 내부 저장은 그 문자의 역순입니다.'),
       ('do_div(n,100000000) 뒤 n의 의미는?', '나눗셈의 몫이다', '원래 숫자를 그대로 유지한다', 'do_div는 나머지를 반환하면서 첫 인자인 n을 몫으로 갱신합니다. 다음 묶음은 수정된 n에서 읽습니다.')],
      [('묶음 수의 한도', 'unsigned long long의 최대값은 decimal 20자리입니다. 두 개의 8자리 아래 묶음과 남은 최상위 최대 4자리로 표현할 수 있습니다.'),
       ('전체 문자열 방향', '낮은 묶음을 먼저 역순으로 저장하고 높은 묶음을 뒤에 이어 붙입니다. 전체 buffer를 뒤집으면 높은 자릿수부터 나타납니다. 단순히 각 묶음만 뒤집어 출력하면 묶음 순서가 틀릴 수 있습니다.')])
    lesson('32bit Decimal 분해·16bit Limb와 Carry', 'put_dec_helper4',
      '64bit division을 피하는 다른 구현에서 수의 분해와 각 묶음 사이의 carry 전달을 이해합니다.',
      '32bit long·64bit long long 분기는 n을 16bit 단위 d0부터 d3으로 나눕니다. 2^16, 2^32, 2^48의 decimal 계수를 10000 단위로 쪼개 q를 누적합니다. put_dec_helper4는 (x*(uint64_t)0x346DC5D7)>>43으로 몫을 계산하고 x-q*10000을 full4로 저장한 뒤 몫을 반환합니다. 이 carry를 다음 4자리 묶음에 더합니다.',
      '64bit 구현과 같은 결과를 내는 선택 분기이지만 내부 계산 경로는 다릅니다. Helper의 입력 범위와 4자리 buffer 공간을 유지합니다. 32bit 분기를 64bit 호스트에서 산술 시험하더라도 실제 32bit 커널 실행 증명이라고 표현하지 않습니다.',
      'd1·d2·d3 분해, 네 묶음 계수, helper의 반환 몫을 따라가세요.',
      [('helper가 저장한 나머지 다음 반환하는 값은?', '다음 묶음에 더할 몫이다', '이미 출력한 문자열의 길이이다', '정수 x를 10000*q+remainder로 나눕니다. Remainder를 저장하고 q를 carry로 넘깁니다.'),
       ('최상위 q가 0이면 끝의 0 문자를 줄이는 이유는?', '역순 buffer의 불필요한 선행 0을 제거한다', '숫자 중간의 모든 0을 지운다', '역순 buffer 끝에 있는 0은 정방향 출력에서 맨 앞에 오는 0입니다. 값 내부의 0을 제거하는 과정이 아닙니다.')],
      [('계수의 유래', '예를 들어 65536은 10000*6+5536입니다. d1의 낮은 묶음에는 5536*d1, 다음 묶음에는 6*d1을 더합니다. 나머지 높은 limb도 같은 방식으로 계수를 나눕니다.'),
       ('정확성의 범위', '원본은 helper 근사식이 x<1128869999에서 정확하고 실제 호출 최대값이 1125520955라고 적습니다. 이 상수를 모든 unsigned 값의 일반 나눗셈 대체로 사용하지 않습니다.')])
    lesson('Num To Str·폭 검사와 NUL 없는 결과', 'num_to_str',
      '숫자 문자열 API에서 저장 가능한 길이와 실제 반환 길이, 종료 문자의 계약을 구분합니다.',
      'num<=9이면 임시 배열에 한 문자를 직접 저장하고 그 외에는 put_dec의 역순 결과를 받습니다. len>size 또는 width>size이면 0을 반환합니다. Width가 더 크면 앞에 공백을 채우고 tmp를 뒤에서 앞으로 복사해 정방향 숫자를 출력합니다. 반환은 len+padding이며 NUL을 추가하는 코드가 없습니다.',
      '반환 길이만큼의 byte로 결과를 사용하거나 별도의 여유 byte에 caller가 NUL을 붙입니다. Width는 최소 폭이므로 숫자가 더 길다고 잘라내지 않습니다. 실패를 빈 문자열과 동일하게 처리하지 않고 반환 0을 확인합니다.',
      '한 자리 분기, 두 용량 비교, 공백 채움, 역순 복사를 읽으세요.',
      [('num=123,size=3,width=2의 결과는?', '123 세 byte와 반환 3이다', '23 두 byte와 반환 2이다', 'Width는 최소 폭입니다. 숫자 길이를 줄이지 않으며 size=3에 세 byte가 맞습니다.'),
       ('size가 숫자 길이와 정확히 같으면 NUL까지 저장하는가?', '숫자 byte만 저장한다', '마지막 숫자를 NUL로 바꾼다', 'num_to_str은 종료 문자를 제공하지 않습니다. 문자열 API에 넘기려면 caller가 공간과 종료를 별도로 준비합니다.')],
      [('실패와 부분 쓰기', '두 용량 검사는 목적 buffer를 채우기 전에 있습니다. 이 경로에서 길이 초과이면 0을 반환하고 목적 buffer를 쓰지 않습니다.'),
       ('정렬된 임시 공간', 'tmp는 sizeof(num)*3이고 __aligned(2)입니다. 내부 u16 두 자리 저장의 alignment 요구를 만족시키며 외부 buf에는 한 byte씩 복사합니다.')])
    lesson('숫자 Format·부호 Prefix와 Padding 순서', 'number',
      '출력 폭, precision, 부호, 진법 prefix를 결합하는 순서가 실제 결과를 어떻게 결정하는지 배웁니다.',
      'number는 printf_spec의 flags·base·폭·precision으로 작동합니다. LEFT이면 ZEROPAD를 지웁니다. 부호와 0x 또는 0 prefix의 폭을 먼저 빼고 실제 숫자를 역순 tmp에 생성합니다. Decimal은 put_dec, octal·hex는 mask와 3·4bit shift를 사용합니다. 숫자 길이보다 작은 precision은 숫자 길이로 올린 뒤 앞 공백, 부호, prefix, 폭 padding, precision 0, 숫자, 뒤 공백 순서로 출력합니다.',
      '형식 파서가 만든 유효 spec으로 사용합니다. 각 쓰기는 buf<end를 검사하지만 logical pointer는 계속 전진해 필요한 길이를 추적합니다. 함수 자체는 NUL을 붙이지 않습니다. Width가 작아도 큰 숫자를 잘라내는 옵션이라고 이해하지 않습니다.',
      'LEFT의 zero 제거, field_width 감소, 저장 조건과 pointer 증가를 읽으세요.',
      [('부호 있는 -42를 폭 5와 ZEROPAD로 출력하면?', '-0042이다', '00-42이다', '부호를 먼저 출력하고 남은 폭을 0으로 채웁니다. 부호 byte도 전체 폭에 포함됩니다.'),
       ('LEFT와 ZEROPAD가 동시에 있으면?', 'LEFT가 ZEROPAD를 지우고 뒤를 공백으로 채운다', '앞뒤 모두 0으로 채운다', '함수 시작 부분의 flags &= ~ZEROPAD가 충돌을 해소합니다. 마지막 loop가 남은 폭을 공백으로 채웁니다.')],
      [('자료구조', 'printf_spec은 type:8, field_width:24, flags:8, base:8, precision:16의 packed bit field이며 static_assert로 8byte를 확인합니다. Signed 폭·precision과 unsigned flags의 역할이 다릅니다.'),
       ('정해진 Flag 값', 'SIGN=1, ZEROPAD=16, SMALL=32는 계산에 쓰이는 값입니다. Space에 ZEROPAD를 더하면 ASCII 0, 대문자 hex와 SMALL을 OR하면 소문자가 됩니다. Static assert가 이 전제를 확인합니다.'),
       ('부호 경계', 'signed 최소값의 음수화를 포함하는 원본 산술은 커널 빌드의 signed overflow 처리 조건을 함께 읽어야 합니다. 일반 사용자 C를 다른 옵션으로 컴파일해 같은 의미를 무조건 가정하지 않습니다.')])
    lesson('문자열 Format·Precision과 오른쪽 이동', 'widen_string',
      '숫자와 달리 이미 쓴 문자열을 이동해 폭을 맞추는 알고리즘과 출력 잘림의 관계를 이해합니다.',
      'string_nocheck는 precision만큼 문자를 읽되 NUL에서 멈추고 실제로 저장되지 못해도 logical len과 buf를 전진시킵니다. Widen_string은 len이 폭보다 작을 때 부족한 공백 수를 계산합니다. Right 정렬이면 move_right로 이미 쓴 문자를 뒤로 옮기고 앞을 공백으로 채웁니다. LEFT이면 뒤에 공백을 씁니다. move_right는 남은 실제 buffer 크기로 이동 길이를 줄이고 memmove를 사용합니다.',
      '유효 문자열 주소와 spec을 제공합니다. 겹치는 영역 이동에서 memcpy로 바꾸지 않습니다. 반환 pointer는 필요한 출력 길이를 반영하며 실제 저장 byte와 다를 수 있습니다. 이 helper의 반환만으로 buffer가 NUL 종료되었다고 해석하지 않습니다.',
      'logical len, memmove 중첩, 공간<=공백이면 공백만 채우는 경로를 읽으세요.',
      [('문자열 ab를 폭 5의 right 정렬로 만들면?', '앞 공백 3개 뒤 ab이다', 'ab 뒤 공백 3개이다', 'move_right가 문자를 세 칸 옮긴 뒤 앞을 공백으로 채웁니다. LEFT일 때만 뒤 공백 경로를 선택합니다.'),
       ('옮길 byte 영역이 겹칠 수 있는데 사용하는 함수는?', 'memmove이다', '언제나 겹치지 않는 memcpy이다', '같은 출력 buffer 안에서 오른쪽으로 이동하므로 겹침을 다룰 수 있는 memmove가 필요합니다.')],
      [('출력 잘림', '실제 남은 공간이 공백 수보다 작거나 같으면 move_right는 그 공간을 공백으로 채우고 돌아갑니다. Logical 결과 전체와 저장 가능한 앞부분의 차이를 문제 풀이에서 구분합니다.'),
       ('Precision', 'precision 0이면 문자열 문자를 읽지 않습니다. 일반 무제한 문자열 spec에서는 -1을 사용하지만 이 값이 loop와 어떻게 결합하는지도 파서의 유효 spec 계약과 함께 읽습니다.')])
    lesson('출력 Pointer 사전 검사·Null과 Error 표현', 'check_pointer_msg',
      '로그 출력 안에서 잘못된 pointer를 처리할 때 간단한 분류와 실제 접근 안전성 검증의 한계를 배웁니다.',
      'check_pointer_msg는 NULL이면 (null), 주소가 PAGE_SIZE보다 작거나 IS_ERR_VALUE이면 (efault), 나머지는 NULL 메시지를 반환합니다. check_pointer는 오류 메시지를 error_string으로 출력하고 -EFAULT를 반환합니다. string은 이 판정을 통과한 주소만 string_nocheck에 전달합니다. error_string은 precision이 -1일 때 2*sizeof(void*)로 제한합니다.',
      '일반 주소가 사전 분류를 통과해도 접근 가능한 살아 있는 문자열인지는 caller가 보장합니다. 출력 경로에서 복잡한 외부 코드를 부르면 printk 재진입으로 무한 반복할 수 있다는 원본 제약을 지킵니다. Error pointer를 정상 문자열로 역참조하지 않습니다.',
      'NULL·낮은 주소·IS_ERR_VALUE 순서와 제한된 메시지 출력 경로를 읽으세요.',
      [('PAGE_SIZE 이상의 일반 주소가 통과하면 매핑 유효성이 증명되는가?', '이 분류만으로 증명되지 않는다', '모든 주소의 page table을 검사했다는 뜻이다', 'Body에는 page table 조회나 객체 수명 검증이 없습니다. 단순한 특별 주소 분류입니다.'),
       ('error_string에서 precision=-1일 때 메시지는?', '2*sizeof(void*)로 길이가 제한된다', '항상 제한 없이 끝까지 읽는다', '이 내부 오류 메시지 경로는 기본 무제한 precision을 주소 크기의 두 배로 바꿉니다.')],
      [('Error 이름 출력', 'err_ptr는 PTR_ERR로 오류를 얻고 errname이 이름을 주면 문자열로 출력합니다. 이름이 없거나 symbolic errname 설정이 없으면 SIGN과 decimal base를 설정해 숫자를 출력합니다.'),
       ('기본 주소 출력 보조', 'pointer_string은 base=16과 SMALL을 설정하고 폭이 -1이면 2*sizeof(ptr)와 ZEROPAD를 사용합니다. 이 보조 함수만 보고 일반 %p의 hashing 정책을 설명하면 안 되며 뒤쪽 pointer dispatcher도 읽어야 합니다.')])
